const raw = $input.first().json;
const item = raw && raw.body ? raw.body : raw;
const startedAt = new Date().toISOString();

if (!item.execution_id) {
  throw new Error('Missing execution_id in payload');
}
if (!item.callback || !item.callback.url || !item.callback.secret) {
  throw new Error('Missing callback.url or callback.secret in payload');
}

const config = item.config || {};
const tone = (config.reply_tone || 'professional').toString().toLowerCase();
const signature = config.signature || 'The Demo Team';
const simulateFailure = config.simulate_failure === true;

const providedItems = item.input && Array.isArray(item.input.items) ? item.input.items : [];
const items = providedItems.length > 0 ? providedItems : [
  {
    from: 'jordan@acme.io',
    subject: 'Need automation help for client onboarding',
    body: 'Hi team — we are scoping a project for client onboarding automation. Could you share pricing and a demo slot this week?'
  },
  {
    from: 'priya@northwind.example',
    subject: 'Question about your platform integrations',
    body: 'Quick one — does your platform support Slack and Gmail out of the box? We are evaluating options before our roadmap planning.'
  }
];

const buildCallback = (status, result, error, metrics) => {
  const finishedAt = new Date().toISOString();
  return {
    callbackUrl: item.callback.url,
    callbackSecret: item.callback.secret,
    callbackBody: {
      execution_id: item.execution_id,
      agent_instance_id: item.agent_instance_id,
      template_id: item.template_id,
      status,
      n8n_execution_id: $execution.id,
      started_at: startedAt,
      finished_at: finishedAt,
      metrics,
      result,
      error
    },
    httpResponse: { received: true, execution_id: item.execution_id, status }
  };
};

if (simulateFailure) {
  return [{
    json: buildCallback(
      'failed',
      null,
      { code: 'MOCK_PROVIDER_TIMEOUT', message: 'Simulated provider timeout for demo', retryable: true },
      { input_count: items.length, output_count: 0, error_count: items.length, tokens_input: 0, tokens_output: 0, estimated_cost_usd: 0 }
    )
  }];
}

const toneOpener = {
  professional: 'Thank you for reaching out.',
  friendly: 'Thanks so much for getting in touch!',
  concise: 'Thanks for the note.'
}[tone] || 'Thank you for reaching out.';

const toneCloser = {
  professional: 'Looking forward to your response.',
  friendly: 'Happy to chat whenever works for you.',
  concise: 'Let me know a good time.'
}[tone] || 'Looking forward to your response.';

const drafts = items.map((email) => {
  const original = (email.subject || '').trim();
  const subject = original.toLowerCase().startsWith('re:') ? original : `Re: ${original || 'your message'}`;
  const snippet = (email.body || '').split(/\s+/).slice(0, 18).join(' ');
  const body = [
    `Hi${email.from ? ' ' + email.from.split('@')[0] : ''},`,
    '',
    `${toneOpener} I read your note: "${snippet}${snippet ? '…' : ''}"`,
    'A teammate will follow up shortly with the details you asked about. In the meantime, here is a 15-minute slot you can grab if useful: https://demo.invalid/book.',
    '',
    toneCloser,
    '',
    signature
  ].join('\n');

  return {
    from: email.from || null,
    original_subject: email.subject || null,
    subject,
    body,
    approval_status: 'waiting_for_review'
  };
});

const tokensIn = items.reduce((sum, e) => sum + ((e.subject || '').length + (e.body || '').length), 0);
const tokensOut = drafts.reduce((sum, d) => sum + d.body.length + d.subject.length, 0);
const summary = `${drafts.length} draft${drafts.length === 1 ? '' : 's'} created and waiting for approval.`;

return [{
  json: buildCallback(
    'success',
    {
      summary,
      data: {
        items_processed: drafts.length,
        drafts,
        summary
      }
    },
    null,
    {
      input_count: items.length,
      output_count: drafts.length,
      error_count: 0,
      tokens_input: Math.ceil(tokensIn / 4),
      tokens_output: Math.ceil(tokensOut / 4),
      estimated_cost_usd: Number((drafts.length * 0.0025).toFixed(4))
    }
  )
}];
